class Solution {
public:
    int minImpossibleOR(std::vector<int>& nums) {
        std::unordered_set<int> s(nums.begin(), nums.end());
        int val = 1;
        while (s.count(val)) {
            val <<= 1;
        }
        return val;
    }
};

class Solution {
    public int minImpossibleOR(int[] nums) {
        java.util.Set<Integer> s = new java.util.HashSet<>();
        for (int x : nums) {
            s.add(x);
        }
        int val = 1;
        while (s.contains(val)) {
            val <<= 1;
        }
        return val;
    }
}

var minImpossibleOR = function(nums) {
    const s = new Set(nums);
    let val = 1;
    while (s.has(val)) {
        val <<= 1;
    }
    return val;
};
